package com.rain.browser.downloads

import android.util.Base64
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

class VideoMediaInspectorInstrumentedTest {
    @Test
    fun inspectsValidMp4DurationAndDecodableFrame() {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val file = File(context.cacheDir, "rain-media-inspector-fixture.mp4")
        try {
            file.writeBytes(Base64.decode(VALID_MP4_BASE64, Base64.DEFAULT))
            val metadata = VideoMediaInspector.inspect(file)
            assertEquals(1_000L, metadata.durationMs)
        } finally {
            file.delete()
        }
    }

    private companion object {
        const val VALID_MP4_BASE64 = ""
    }
}
